function validate([s, k, letter, repetition]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 50000) return 's needs 1 to 5 * 10^4 characters.';
  if (!/^[a-z]+$/.test(s)) return 's may contain only lowercase English letters.';
  if (typeof letter !== 'string' || !/^[a-z]$/.test(letter)) return 'letter is one lowercase English letter.';
  if (!Number.isInteger(k) || !Number.isInteger(repetition)) return 'k and repetition are whole numbers.';
  if (repetition < 1 || repetition > k || k > s.length) return 'Need 1 <= repetition <= k <= s.length.';
  let count = 0;
  for (const ch of s) if (ch === letter) count++;
  if (count < repetition) return 'letter must occur in s at least repetition times.';
  return null;
}

