function smallestSubsequence(s, k, letter, repetition) {
  const n = s.length;
  let lettersLeft = 0;
  for (const ch of s) {
    if (ch === letter) lettersLeft++;
  }
  const stack = [];
  let lettersInStack = 0;

  for (let i = 0; i < n; i++) {
    const ch = s[i];
    while (stack.length > 0 && stack[stack.length - 1] > ch && stack.length - 1 + n - i >= k) {
      const top = stack[stack.length - 1];
      if (top === letter && lettersInStack - 1 + lettersLeft < repetition) {
        break;
      }
      stack.pop();
      if (top === letter) {
        lettersInStack--;
      }
    }
    if (stack.length < k) {
      if (ch === letter) {
        stack.push(ch);
        lettersInStack++;
      } else if (k - stack.length > repetition - lettersInStack) {
        stack.push(ch);
      }
    }
    if (ch === letter) {
      lettersLeft--;
    }
  }
  return stack.join('');
}

