function smallestSubsequence(s, k, letter, repetition) {
  const n = s.length;
  let best = null;
  for (let mask = 0; mask < (1 << n); mask++) {
    let picked = '';
    let count = 0;
    for (let i = 0; i < n; i++) {
      if (mask & (1 << i)) {
        picked += s[i];
        if (s[i] === letter) count++;
      }
    }
    if (picked.length === k && count >= repetition && (best === null || picked < best)) best = picked;
  }
  return best;
}

