function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const n = large ? int(6000, 10000) : int(1, 12);
  const alphabet = large ? int(1, 26) : int(1, 4);
  const offset = int(0, 26 - alphabet);
  let s = '';
  for (let i = 0; i < n; i++) s += String.fromCharCode(97 + offset + int(0, alphabet - 1));
  const letter = s[int(0, n - 1)];
  let count = 0;
  for (const ch of s) if (ch === letter) count++;
  const k = rand() < 0.2 ? n : int(1, n);
  const most = Math.min(count, k);
  const roll = rand();
  const repetition = roll < 0.25 ? most : roll < 0.4 ? 1 : int(1, most);
  return [s, k, letter, repetition];
}
